#include "ms_color_pipeline.hpp"
#include <algorithm>
#include <cmath>
namespace ms { ColorPipeline::ColorPipeline():spaces_{{"Linear",false,1},{"sRGB",true,2.4f},{"ACEScg",false,1},{"ACES2065-1",false,1},{"Rec.709",true,2.4f},{"Display P3",true,2.4f},{"Rec.2020",true,2.4f}}{} Error ColorPipeline::transform(ImageBuffer&img,const std::string&src,const std::string&dst)const{if(!img.valid()||img.format()!=PixelFormat::RGBA8)return Error::make(ErrorCode::InvalidArgument,"color transform needs RGBA8");if(src==dst)return Error::success();auto l=[](float c,const std::string&s){return(s=="sRGB"||s=="Rec.709"||s=="Display P3"||s=="Rec.2020")?color::srgb_to_linear(c):c;};auto d=[](float c,const std::string&s){return(s=="sRGB"||s=="Rec.709"||s=="Display P3"||s=="Rec.2020")?color::linear_to_srgb(c):c;};uint8_t*p=img.data();for(int i=0,n=img.width()*img.height();i<n;++i){for(int k=0;k<3;++k)p[k]=(uint8_t)(std::clamp(d(l(p[k]/255.f,src),dst),0.f,1.f)*255+.5f);p+=4;}return Error::success();} Error ColorPipeline::apply_grade(ImageBuffer&img,float e,float c,float s)const{if(!img.valid()||img.format()!=PixelFormat::RGBA8)return Error::make(ErrorCode::InvalidArgument,"grade needs RGBA8");float em=std::pow(2.f,e);uint8_t*p=img.data();for(int i=0,n=img.width()*img.height();i<n;++i){float r=p[0]/255.f,g=p[1]/255.f,b=p[2]/255.f;r*=em;g*=em;b*=em;r=(r-.5f)*c+.5f;g=(g-.5f)*c+.5f;b=(b-.5f)*c+.5f;float y=.2126f*r+.7152f*g+.0722f*b;r=y+(r-y)*s;g=y+(g-y)*s;b=y+(b-y)*s;p[0]=(uint8_t)(std::clamp(r,0.f,1.f)*255+.5f);p[1]=(uint8_t)(std::clamp(g,0.f,1.f)*255+.5f);p[2]=(uint8_t)(std::clamp(b,0.f,1.f)*255+.5f);p+=4;}return Error::success();}}
